import { Check, Trash2, X, Sparkles } from "lucide-react";
import { type CommentRow, formatCommentTimeAgo } from "@/lib/comments.functions";

type Props = {
  comments: CommentRow[];
  selectedIds?: Set<number>;
  allSelected?: boolean;
  onToggleSelectAll?: () => void;
  onToggleSelectOne?: (id: number) => void;
  onSetStatus: (id: number, status: "Approved" | "Pending" | "Spam") => void;
  onDelete: (id: number) => void;
  onAiReply?: (comment: CommentRow) => void;
};

const badge: Record<CommentRow["status"], string> = {
  Approved: "bg-emerald-50 text-emerald-700 border-emerald-200",
  Pending: "bg-amber-50 text-amber-700 border-amber-200",
  Spam: "bg-red-50 text-red-700 border-red-200",
};

export function CommentTable({
  comments,
  selectedIds,
  allSelected,
  onToggleSelectAll,
  onToggleSelectOne,
  onSetStatus,
  onDelete,
  onAiReply,
}: Props) {
  return (
    <div className="overflow-x-auto rounded-xl border border-slate-200 bg-white shadow-sm">
      <table className="w-full min-w-[650px] text-left text-sm">
        <thead className="border-b border-slate-200 bg-slate-50 text-xs font-bold uppercase tracking-wider text-slate-500">
          <tr>
            {onToggleSelectAll && (
              <th className="px-4 py-3 w-10 text-center">
                <input
                  type="checkbox"
                  checked={allSelected}
                  onChange={onToggleSelectAll}
                  className="h-4 w-4 rounded border-slate-300 text-slate-900 focus:ring-slate-900 cursor-pointer"
                  title="Select / Deselect all comments on this page"
                  aria-label="Select all comments on this page"
                />
              </th>
            )}
            <th className="px-4 sm:px-5 py-3">User &amp; Time</th>
            <th className="px-4 sm:px-5 py-3">Comment Body</th>
            <th className="px-4 sm:px-5 py-3">Article</th>
            <th className="px-4 sm:px-5 py-3">Status</th>
            <th className="px-4 sm:px-5 py-3 text-right">Actions</th>
          </tr>
        </thead>
        <tbody className="divide-y divide-slate-100">
          {comments.map((c) => {
            const isSelected = selectedIds?.has(c.id) ?? false;
            return (
              <tr
                key={c.id}
                className={`transition-colors ${
                  isSelected ? "bg-amber-50/60" : "hover:bg-slate-50/70"
                }`}
              >
                {onToggleSelectOne && (
                  <td className="px-4 py-3 text-center">
                    <input
                      type="checkbox"
                      checked={isSelected}
                      onChange={() => onToggleSelectOne(c.id)}
                      className="h-4 w-4 rounded border-slate-300 text-slate-900 focus:ring-slate-900 cursor-pointer"
                      aria-label={`Select comment #${c.id}`}
                    />
                  </td>
                )}
              <td className="px-5 py-3">
                <p className="font-semibold text-slate-900">{c.user || "Anonymous"}</p>
                <p className="text-xs text-slate-500">{c.email}</p>
                <div className="flex items-center gap-1.5 mt-0.5">
                  <span
                    className="text-[11px] font-medium text-blue-700 bg-blue-50 px-1.5 py-0.2 rounded"
                    title={c.createdAt ? new Date(c.createdAt).toLocaleString() : c.date}
                  >
                    {formatCommentTimeAgo(c.createdAt || c.date)}
                  </span>
                  {c.parentId && (
                    <span className="text-[10px] text-slate-400 font-mono">
                      ↳ reply to #{c.parentId}
                    </span>
                  )}
                </div>
              </td>
              <td className="px-5 py-3 text-xs text-slate-700 max-w-sm whitespace-pre-line">{c.body}</td>
              <td className="px-5 py-3 text-xs text-slate-600 font-medium max-w-xs truncate">
                <a
                  href={`/news/${c.articleSlug}`}
                  target="_blank"
                  rel="noopener noreferrer"
                  className="hover:underline text-blue-600"
                >
                  {c.articleTitle || c.articleSlug}
                </a>
              </td>
              <td className="px-5 py-3">
                <span
                  className={`inline-flex rounded-full border px-2.5 py-0.5 text-xs font-semibold ${badge[c.status]}`}
                >
                  {c.status}
                </span>
              </td>
              <td className="px-5 py-3 text-right">
                <div className="inline-flex items-center gap-1.5">
                  {onAiReply && (
                    <button
                      onClick={() => onAiReply(c)}
                      title="Generate AI Reply to this comment"
                      className="rounded-md border border-blue-200 bg-blue-50 px-2 py-1 text-xs font-semibold text-blue-700 hover:bg-blue-100 flex items-center gap-1 transition"
                    >
                      <Sparkles className="h-3 w-3 text-blue-600" />
                      <span>AI Reply</span>
                    </button>
                  )}
                  {c.status !== "Approved" && (
                    <button
                      onClick={() => onSetStatus(c.id, "Approved")}
                      title="Approve Comment"
                      className="rounded-md border border-emerald-200 bg-emerald-50 p-1.5 text-emerald-700 hover:bg-emerald-100"
                    >
                      <Check className="h-3.5 w-3.5" />
                    </button>
                  )}
                  {c.status !== "Spam" && (
                    <button
                      onClick={() => onSetStatus(c.id, "Spam")}
                      title="Mark as Spam"
                      className="rounded-md border border-amber-200 bg-amber-50 p-1.5 text-amber-800 hover:bg-amber-100"
                    >
                      <X className="h-3.5 w-3.5" />
                    </button>
                  )}
                  <button
                    onClick={() => onDelete(c.id)}
                    title="Delete Comment"
                    className="rounded-md border border-red-200 bg-red-50 p-1.5 text-red-600 hover:bg-red-100"
                  >
                    <Trash2 className="h-3.5 w-3.5" />
                  </button>
                </div>
              </td>
            </tr>
          );
        })}

          {comments.length === 0 && (
            <tr>
              <td colSpan={6} className="px-5 py-8 text-center text-xs text-slate-400">
                No comments found in this tab.
              </td>
            </tr>
          )}
        </tbody>
      </table>
    </div>
  );
}
